#include <stdio.h>
#include <string.h>

int main(void) {
    const char source[] = "C arrays";
    char destination[16];
    size_t needed = sizeof source;
    if (needed <= sizeof destination) {
        memcpy(destination, source, needed);
        puts(destination);
    } else {
        puts("Destination is too small");
    }
    return 0;
}

#include <stddef.h>
#include <stdio.h>

int get_value(const int values[], size_t count, size_t index, int *out) {
    if (values == NULL || out == NULL || index >= count) return 0;
    *out = values[index];
    return 1;
}

int main(void) {
    int data[] = { 4, 8, 12 };
    int result;
    if (get_value(data, 3, 2, &result)) printf("%d\n", result);
    return 0;
}
